/// Identifies a channel layout as used by the rendering matrix tables:
/// IAMF loudspeaker layouts as inputs, BS.2051 sound systems (plus IAMF
/// extensions) as outputs.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
